    'sources': ["Introduction to Algorithms (CLRS)", "Cracking the Coding Interview by Gayle Laakmann McDowell"],
    'uncertainty': "",
}

ML = {
    'answer': "Machine learning is about building models that learn patterns from data instead of following hand-written rules. Supervised learning uses labeled data, unsupervised learning finds structure in unlabeled data, and reinforcement learning learns from rewards. Know overfitting versus underfitting, the bias-variance tradeoff, regularization, cross-validation, and metrics like precision, recall, and F1. Assuming a mid-level software engineer, explain these simply with a concrete example.",
    'practice_questions': ["What is the difference between supervised and unsupervised learning?", "How would you detect and reduce overfitting?", "When would you prefer precision over recall?", "How would you split data for training and evaluation?"],
    'tips': ["Explain each concept with a short real-world example.", "State the tradeoffs of any model you choose.", "Always mention how you would evaluate the model.", "Ask clarifying questions about data and goals first."],
    'sources': ["Pattern Recognition and Machine Learning by Christopher Bishop", "Hands-On Machine Learning with Scikit-Learn, Keras, and TensorFlow by Aurelien Geron", "scikit-learn official documentation"],
