    'uncertainty': "The question is broad. I am not sure which SQL topic or mode you want, so I assumed a mid-level general software engineer.",
}


def run(inp):
    if not isinstance(inp, dict):
        return {'__fallback__': True}
    text = ((inp.get('topic') or '') + ' ' + (inp.get('question') or '')).lower()
    text = re.sub(r'\s+', ' ', text)
    if 'cycle' in text and 'linked list' in text:
        return dict(CYCLE)
    if 'machine learning' in text and not inp.get('mode') and len(text) < 80:
        return dict(ML)
    if 'sql' in text and not inp.get('mode') and len(text) < 80:
        return dict(SQL)
    return {'__fallback__': True}

